script:
frappe.call({
  method: "frappe.client.get",
  args: {
    doctype: "Custom Control Settings",
    name: "Custom Control Settings"
  },
  callback: function(r) {
    const settings = r.message;

    if (settings.enable_unbilled_stock_access == 0 ) {
    console.log($('#updated-stock-sale').length); // should be > 0

      // 🚫 Hide dashboard tile or link
      $("#updated-stock-sale").addClass("hidden"); // use your actual tile ID or class
      $(".updated-stock").css("display","none");
      $('.btn[data-label="Add Update Stock"]').addClass("hidden"); 

      $("<style>.hidden { display: none !important; }</style>").appendTo("head");

        const hideTile = setInterval(() => {
          const tile = document.getElementById("updated-stock-sale");
          if (tile) {
            tile.classList.add("hidden");
            clearInterval(hideTile);
          }
        }, 300);


    } else 
    {

         $('.btn[data-label="Add Update Stock"]').show();


      // 🚫 Hide dashboard tile or link
      $('#updated-stock-sale').show(); // use your actual tile ID or class
    }
  }
});

style:
.erp-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  font-family: Arial, sans-serif;
}
.erp-tile {
  width: 160px;
  height: 140px;
  background: #f4f6f8;
  border-radius: 8px;
  text-align: center;
  padding: 16px;
  box-shadow: 0 2px 6px rgba(0,0,0,0.1);
  transition: 0.2s ease;
}
.erp-tile:hover {
  background: #e2e6ea;
  transform: translateY(-2px);
}
.hidden {
  display: none !important;
}

.erp-icon {
  font-size: 32px;
  margin-bottom: 12px;
  display: block;
}
.erp-label {
  font-weight: bold;
  color: #333;
  text-decoration: none;
}
